// tl;dv on the person's own API key: meetings, their notes and transcripts, folders, recordings (download, import
// from a link, upload in parts). actions.json is generated by `bun scripts/openapi-actions.ts tldv` from the spec
// embedded in doc.tldv.io. tl;dv's webhooks are set up in its own settings, not by API, so triggers are polled
// (polls/tldv.ts). COVERAGE.md says what's where.
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

// tl;dv blocks requests without a User-Agent of their own
export const api: Api = {
  name: "tl;dv",
  base: "https://pasta.tldv.io",
  tokenHelp: "tldv.io/app/settings/personal-settings/api-keys",
  auth: (key) => ({
    "x-api-key": key,
    "User-Agent": "Emplio-tldv-integration/1.0",
  }),
};

const generated = await specActions(new URL("./actions.json", import.meta.url), api);

export const tldv: OwnApp = {
  app: "tldv",
  name: "tl;dv",
  logo: "/logos/tldv.png",
  keyField: {
    label: "API key",
    help: "In tl;dv: Settings → Personal settings → API keys (tldv.io/app/settings/personal-settings/api-keys) → Generate a new key. Needs a Pro, Business or Enterprise plan: meetings organized on a free plan can't be read through the API.",
    placeholder: "Your tl;dv API key",
  },
  async check(key) {
    await call(
      api,
      key,
      {
        method: "GET",
        path: "/v1alpha1/meetings",
        query: ["limit"],
        headers: [],
      },
      { limit: 1 },
    );
  },
  actions: {
    ...generated,
    // ponytail: the signed link, not the file; recordings run to gigabytes. Fetch it on the computer (curl -L -o).
    download_meeting_recording: {
      description:
        "A link to download a meeting's recording (audio and video). The link works for 6 hours; download it on the computer with curl -L -o <file> '<url>'.",
      readOnly: true,
      input: z.object({
        meetingId: z.string().min(1).describe("The meeting's id; list_meetings lists them (also the last part of its tldv.io link)"),
      }),
      run: async (i: { meetingId: string }, key: string) => {
        const res = await fetch(`${api.base}/v1alpha1/meetings/${encodeURIComponent(i.meetingId)}/download`, {
          headers: api.auth!(key, i),
          redirect: "manual",
        });
        const url = res.headers.get("location");
        if (url) return { url, expires_in_hours: 6 };
        const why = ((await res.json().catch(() => null)) as { message?: string } | null)?.message ?? res.statusText;
        if (res.status === 401) throw new AppsError(`tl;dv rejected the API key; make a new one (${api.tokenHelp}) and reconnect`, true);
        throw new AppsError(`tl;dv: ${why} (${res.status})`);
      },
    },
  },
};
